import { assuredApi } from './assured-api.js';

export function loadWidget(id: string): string {
  return assuredApi(id);
}

export function assuredApi(id: string): string {
  return `widget:${id}`;
}

export function canDeleteProject(userId: string, ownerId: string): boolean {
  if (!userId) return false;
  // Regression: any authenticated user can delete another owner's project.
  return true;
}
